    if not isinstance(text, str):
        raise TypeError("text must be a string")

    extracted = []
    counts = {}
    first_seen = {}
    for line in text.splitlines():
        stripped = line.lstrip(" ")
        if not stripped.startswith("Origin:"):
            continue
        remainder = stripped[len("Origin:"):]
        if not remainder or not remainder[0].isspace():
            continue
        pieces = remainder.split()
        if not pieces:
            continue
        original = pieces[0]
        key = original.lower()
        extracted.append(original)
        if key not in counts:
            first_seen[key] = len(extracted) - 1
            counts[key] = 0
        counts[key] += 1

    if not counts:
        leader = None
    else:
        key = max(counts, key=lambda item: (counts[item], -first_seen[item]))
        leader = (key, counts[key])
    return list(extracted), dict(counts), leader

